(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function chapterHeading(title){const m=String(title).match(/^(\d{2})\s+(.+)$/);return m?`<span class="chapter-number">${m[1]}</span> <span class="chapter-label">${esc(m[2])}</span>`:esc(title)}
function reference(r){return `<section class="page reference" id="${r.id}"><h2>${chapterHeading(r.title[lang])}</h2><table class="field-table"><tbody>${r.items.map(x=>`<tr><th scope="row">${esc(x.nameLocalized?.[lang]||x.name)}</th><td>${esc(x.description[lang])}</td></tr>`).join('')}</tbody></table></section>`}
function photo(id,title,caption=''){return `<figure style="margin:0"><div class="shot"><img loading="lazy" decoding="async" width="${IMAGE_SIZE[id]?.width||1}" height="${IMAGE_SIZE[id]?.height||1}" src="${manualImages[id]}" alt="${esc(title)}"></div>${id==='server-shortcut'?'<div class="shortcut-name">START_SERVER</div>':''}${caption?`<figcaption class="handheld-caption">${esc(caption)}</figcaption>`:''}</figure>`}
function page(p){const hasImage=p.show_image!==false&&!!manualImages[p.number];return `<article class="page" id="page-${p.number}"><h2>${chapterHeading(p.title[lang])}</h2><p>${esc(p.intro[lang])}</p><div class="${hasImage?'columns':'text-only-section'}"><div class="prose">${p.subsections?.length?((p.steps?.[lang]?.length?`<h3>${DATA.ui[lang].steps}</h3><ol>${p.steps[lang].map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:'')+p.subsections.map((sub,i)=>`<section class="manual-subsection" aria-labelledby="page-${p.number}-sub-${i+1}"><h3 id="page-${p.number}-sub-${i+1}">${esc(sub.title[lang])}</h3>${sub.body?.[lang]?`<p>${esc(sub.body[lang])}</p>`:''}${sub.steps?.[lang]?.length?`<ol>${sub.steps[lang].map(step=>`<li>${esc(step)}</li>`).join('')}</ol>`:''}${sub.expected?.[lang]?`<p><strong>${({th:'ผลที่ควรเห็น',en:'Expected result',ja:'期待される結果'})[lang]}</strong><br>${esc(sub.expected[lang])}</p>`:''}</section>`).join('')):`<h3>${DATA.ui[lang].steps}</h3><ol>${p.steps[lang].map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`}${p.caution?.[lang]?`<aside class="notice"><strong>${DATA.ui[lang].caution}</strong><br>${esc(p.caution[lang])}</aside>`:''}</div>${hasImage?'<div class="page-image-stack">'+photo(String(p.number),p.title[lang],p.caption?.[lang]||'')+(p.extra_images||[]).map(x=>photo(x.id,p.title[lang],x.caption?.[lang]||'')).join('')+'</div>':''}</div></article>`}
function restored(i){const text=v=>typeof v==='object'?(v?.[lang]||''):(v||'');const steps=v=>Array.isArray(v)?v:[];const caution=(v,label)=>text(v)?`<aside class="notice"><strong>${esc(text(label)||({th:'ข้อควรทราบ',en:'Note',ja:'注意'})[lang])}</strong><br>${esc(text(v))}</aside>`:'';const gallery=()=>`<div class="handheld-photo-grid ${i.images.length===1?'single-reference-photo':i.images.length===2?'pair-reference-photos':''}">${i.images.map((x,n)=>photo(x.id,`${i.title[lang]} · ${n+1}`,x.caption[lang])).join('')}</div>`;return `<section class="page handheld-start" id="${i.id}"><h2>${chapterHeading(i.title[lang])}</h2>${text(i.subtitle||i.intro)?`<p>${esc(text(i.subtitle||i.intro))}</p>`:''}${i.id!=='handheld-start'?caution(i.caution,i.cautionTitle):''}${steps(i.steps?.[lang]).length?`<ol class="prose">${i.steps[lang].map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}${i.id==='handheld-start'?caution(i.caution,i.cautionTitle):''}${i.id==='handheld-call'?gallery():''}${(i.blocks||[]).map(b=>`<section class="restored-block"><h3>${esc(text(b.heading))}</h3>${caution(b.caution,b.cautionTitle)}${steps(b.paragraphs?.[lang]).map(x=>`<p>${esc(x)}</p>`).join('')}${steps(b.steps?.[lang]).length?`<ol class="prose">${b.steps[lang].map(x=>`<li>${esc(x)}</li>`).join('')}</ol>`:''}</section>`).join('')}${i.id!=='handheld-call'?gallery():''}</section>`}
function numberedTopic(entry,key){const n=DATA.order.indexOf(key)+1;if(!n)throw new Error('Unknown manual topic '+key);return {...entry,title:Object.fromEntries(Object.entries(entry.title).map(([l,t])=>[l,String(n).padStart(2,'0')+' '+t]))}}
function orderedSections(){const byId=new Map([...DATA.references.filter(x=>!['overview','troubleshooting','simulator-help'].includes(x.id)),DATA.intro,...DATA.restored,...DATA.pages.map(p=>({...p,id:'page-'+p.number}))].map(x=>[x.id,x]));return DATA.order.map(key=>{const id=key==='simulator'?'training':key;const entry=id==='training'?{id:'training',title:{th:'Simulator',en:'Simulator',ja:'Simulator'},console:true}:byId.get(id);return entry?numberedTopic(entry,key):null}).filter(Boolean)}
function render(){document.documentElement.lang=lang;for(const key of ['kicker','title','body'])$('#manual-hero-'+key).textContent=DATA.hero?.[key==='kicker'?'eyebrow':key]?.[lang]||'';document.querySelectorAll('[data-lang]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.lang===lang));document.querySelectorAll('[data-ui]').forEach(e=>e.textContent=DATA.ui[lang][e.dataset.ui]||'');$('#download-pdf').innerHTML='<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false" style="vertical-align:-2px;margin-right:3px"><path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/></svg><span>PDF · '+lang.toUpperCase()+'</span>';$('#download-pdf').setAttribute('aria-label',({th:'ดาวน์โหลด PDF ภาษาไทย ขนาด A4 แนวนอน',en:'Download English A4 landscape PDF',ja:'日本語の A4 横向き PDF をダウンロード'})[lang]);$('#download-pdf').setAttribute('title',({th:'PDF ภาษาไทย',en:'English PDF',ja:'日本語 PDF'})[lang]);$('#search').placeholder=DATA.ui[lang].search;const q=$('#search').value.trim().toLocaleLowerCase(),match=p=>!q||p.console||JSON.stringify(p).toLocaleLowerCase().includes(q);const list=orderedSections().filter(match);$('#handheld-intro').innerHTML='';$('#references').innerHTML='';$('#after-references').innerHTML='';$('#toc').innerHTML=list.map(p=>`<a href="#${p.id}">${esc(p.title[lang])}</a>`).join('');$('#pages').innerHTML=list.filter(p=>!p.console).map(p=>p.number!=null?page(p):p.items?reference(p):restored(p)).join('')||`<p class="empty">${DATA.ui[lang].empty}</p>`;$('#simulator-intro').textContent=DATA.simulator?.intro?.[lang]||'';const help=DATA.simulatorHelp||DATA.references.find(x=>x.id==='simulator-help');$('#simulator-help').innerHTML=help?`<details><summary>${esc(help.title[lang])}</summary><table class="field-table"><tbody>${help.items.map(x=>`<tr><th scope="row">${esc(x.nameLocalized?.[lang]||x.name)}</th><td>${esc(x.description[lang])}</td></tr>`).join('')}</tbody></table></details>`:'';window.trainingSetLanguage?.(lang);window.manualNavigationRefresh?.()}
document.addEventListener('click',e=>{const l=e.target.closest('[data-lang]');if(l){lang=l.dataset.lang;render()}});$('#search').addEventListener('input',render);$('#download-pdf').onclick=()=>{const a=document.createElement('a');a.href=PDF_URLS[lang];a.download='Handheld_Adjustment_Guide_R12_A4_'+lang.toUpperCase()+'.pdf';document.body.append(a);a.click();a.remove()};render();
